describe('Table Row Highlight on Hover', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should highlight a row when hovering over it', () => {
    // Get the first row
    cy.get('[data-testid="table-row-1"]').should('be.visible');

    // Hover over the row
    cy.get('[data-testid="table-row-1"]').should('be.visible');
    cy.get('[data-testid="table-row-1"]').trigger('mouseover');

    // Verify the row is highlighted
    cy.get('[data-testid="table-row-1"]').should('have.class', 'highlighted');

    // Verify the background color has changed
    cy.get('[data-testid="table-row-1"]').should('have.css', 'background-color', 'rgba(255, 255, 255, 0.1)');

    // Verify the text color has changed
    cy.get('[data-testid="table-row-1"]').should('have.css', 'color', 'rgba(0, 0, 0, 0.8)');

    // Verify the row is still visible
    cy.get('[data-testid="table-row-1"]').should('be.visible');
  });

  it('should unhighlight a row when hovering off of it', () => {
    // Get the first row
    cy.get('[data-testid="table-row-1"]').should('be.visible');

    // Hover over the row
    cy.get('[data-testid="table-row-1"]').trigger('mouseover');

    // Verify the row is highlighted
    cy.get('[data-testid="table-row-1"]').should('have.class', 'highlighted');

    // Hover off the row
    cy.get('[data-testid="table-row-1"]').trigger('mouseout');

    // Verify the row is no longer highlighted
    cy.get('[data-testid="table-row-1"]').should('not.have.class', 'highlighted');

    // Verify the background color has reverted
    cy.get('[data-testid="table-row-1"]').should('have.css', 'background-color', '');

    // Verify the text color has reverted
    cy.get('[data-testid="table-row-1"]').should('have.css', 'color', '');

    // Verify the row is still visible
    cy.get('[data-testid="table-row-1"]').should('be.visible');
  });
});
